package com.pocketmusic.android;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import java.util.*;
import static org.junit.Assert.*;
public class LiveMusicCatalogTest {
 @Test public void songsComeFromActualMusicCatalogue()throws Exception{Assume.assumeTrue("true".equals(InstrumentationRegistry.getArguments().getString("liveMusic")));List<Track> songs=MusicCatalog.songs("Daft Punk","live-music-test");assertFalse("Music catalogue returned no songs",songs.isEmpty());Set<String> ids=new HashSet<>();for(Track t:songs){assertTrue(t.music);assertTrue(t.durationSeconds>0);assertTrue(t.id.matches("[A-Za-z0-9_-]{11}"));assertFalse(t.title.isBlank());assertTrue(ids.add(t.id));}assertTrue(songs.size()<=20);}
 @Test public void realMusicSearchesBuildMultipleSongShelves()throws Exception{Assume.assumeTrue("true".equals(InstrumentationRegistry.getArguments().getString("liveMusic")));android.content.Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="live-music-profile-"+UUID.randomUUID();java.io.File root=java.nio.file.Files.createTempDirectory(app.getCacheDir().toPath(),"live-music-").toFile();android.content.Context context=new android.content.ContextWrapper(app){public java.io.File getNoBackupFilesDir(){return root;}public java.io.File getCacheDir(){return root;}public android.content.SharedPreferences getSharedPreferences(String key,int mode){return super.getSharedPreferences(name,mode);}};try{MusicTaste.choose(context,"Daft Punk, Dua Lipa",List.of("Acoustic"));Recommendations.fetch(context,"live-music-shelves");assertTrue("Expected mix plus artist discovery sections",Recommendations.shelves(context).size()>=3);assertTrue("Expected more than one small row of music",Recommendations.cached(context).size()>=8);for(Track t:Recommendations.cached(context))assertTrue(t.music);assertTrue(Recommendations.cached(context).size()<=36);}finally{context.deleteSharedPreferences(name);root.delete();}}
}
